import sys
import os

# Increase recursion depth for deep trees
sys.setrecursionlimit(300000)

class Solution:
    def __init__(self, n, edges):
        self.n = n
        self.edges = edges
        self.parent = list(range(n + 1))
        self.rank = [0] * (n + 1)
        self.adj = [[] for _ in range(n + 1)]
        self.mst_edges = set()
        self.mst_weight = 0
        self.is_mst = [False] * len(edges)
        self.edge_to_id = {}

    def find(self, x):
        root = x
        while root != self.parent[root]:
            root = self.parent[root]

        # Path compression
        while x != root:
            nxt = self.parent[x]
            self.parent[x] = root
            x = nxt
        return root

    def union(self, x, y):
        rx, ry = self.find(x), self.find(y)
        if rx == ry:
            return False
        if self.rank[rx] < self.rank[ry]:
            rx, ry = ry, rx
        self.parent[ry] = rx
        if self.rank[rx] == self.rank[ry]:
            self.rank[rx] += 1
        return True

    def build_mst(self):
        # Sort edges by weight for Kruskal's
        sorted_edges = sorted(enumerate(self.edges), key=lambda x: x[1][2])

        for idx, (a, b, w) in sorted_edges:
            self.edge_to_id[(a, b) if a < b else (b, a)] = idx
            if self.union(a, b):
                self.is_mst[idx] = True
                self.mst_edges.add((a, b) if a < b else (b, a))
                self.adj[a].append((b, w))
                self.adj[b].append((a, w))

    def binary_lift_precompute(self):
        LOG = 20
        self.up = [[0] * (self.n + 1) for _ in range(LOG)]
        self.max_edge = [[0] * (self.n + 1) for _ in range(LOG)]
        self.depth = [0] * (self.n + 1)

        # DFS to compute depths and immediate parents
        self.timer = 0

        def dfs(u, p=-1, w=0, d=0):
            self.depth[u] = d
            self.up[0][u] = p
            self.max_edge[0][u] = w
            for v, wt in self.adj[u]:
                if v != p:
                    dfs(v, u, wt, d + 1)

        dfs(1)

        # Binary lifting table
        for j in range(1, LOG):
            for i in range(1, self.n + 1):
                self.up[j][i] = self.up[j-1][self.up[j-1][i]]
                self.max_edge[j][i] = max(self.max_edge[j-1][i], 
                                         self.max_edge[j-1][self.up[j-1][i]])

    def query_max(self, u, v):
        if self.depth[u] < self.depth[v]:
            u, v = v, u

        # Lift u to same depth as v
        max_w = 0
        diff = self.depth[u] - self.depth[v]

        for j in range(20):
            if diff & (1 << j):
                max_w = max(max_w, self.max_edge[j][u])
                u = self.up[j][u]

        if u == v:
            return max_w

        # Lift both until just below LCA
        for j in range(19, -1, -1):
            if self.up[j][u] != self.up[j][v]:
                max_w = max(max_w, self.max_edge[j][u], self.max_edge[j][v])
                u = self.up[j][u]
                v = self.up[j][v]

        # One more step to reach LCA
        max_w = max(max_w, self.max_edge[0][u], self.max_edge[0][v])
        return max_w

    def solve(self):
        self.build_mst()
        self.binary_lift_precompute()

        results = []
        for idx in range(len(self.edges)):
            if not self.is_mst[idx]:
                a, b, w = self.edges[idx]
                a, b = min(a, b), max(a, b)
                max_on_path = self.query_max(a, b)
                results.append(str(max_on_path))

        return '\n'.join(results)

