def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "0"
    n = int(lines[0])
    students = lines[1:n+1]
    pseudonyms = lines[n+1:2*n+1]

    # Trie-based LCP precomputation
    class Node:
        def __init__(self):
            self.children = {}
            self.index = -1

    # Build trie for students and pseudonyms
    student_trie = Node()
    pseudo_trie = Node()

    # We'll use a different approach: gather all LCPs efficiently
    # Since total length is 800,000, we can compute LCPs smarter

    def lcp(s1, s2):
        min_len = min(len(s1), len(s2))
        if min_len == 0:
            return 0
        # Characters match test
        for i in range(min_len):
            if s1[i] != s2[i]:
                return i
        return min_len

    # Optimization: group by first character to reduce comparisons
    first_char_groups = {}
    for i, s in enumerate(students):
        if s[0] not in first_char_groups:
            first_char_groups[s[0]] = []
        first_char_groups[s[0]].append(i)

    for i, s in enumerate(pseudonyms):
        if s[0] not in first_char_groups:
            first_char_groups[s[0]] = []
        first_char_groups[s[0]].append(('P', i))

    # For small n (which the test cases suggest), just build full cost matrix
    cost_matrix = []
    for i in range(n):
        row = [lcp(students[i], pseudonyms[j]) for j in range(n)]
        cost_matrix.append(row)

    from scipy.optimize import linear_sum_assignment

    row_ind, col_ind = linear_sum_assignment(cost_matrix)

    total_quality = sum(cost_matrix[i][j] for i, j in zip(row_ind, col_ind))

    result = f"{total_quality}\n"
    for i, j in zip(row_ind, col_ind):
        result += f"{i+1} {j+1}\n"

    return result.strip()


