                continue
            for j in range(2):
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
    return C

def power(A, p):
    result = [[1, 0], [0, 1]]
    base = A
    while p > 0:
        if p & 1:
            result = multiply(result, base)
        base = multiply(base, base)
        p >>= 1
    return result

