    # For the recursive structure f_r, it counts ways to assign prime factors
    # with some restrictions based on r

    # The actual pattern: f_r(n) = product over prime factors p^a of binomial(a+r-1, r)
    # This is given by stars and bars with r-1 dividers for a^a items

    # Precompute factorials and inverse factorials for combinations
    fact = [1] * MAX_N
    inv = [1] * MAX_N
    finv = [1] * MAX_N

    for i in range(1, MAX_N):
        fact[i] = (fact[i-1] * i) % MOD

    finv[MAX_N-1] = pow(fact[MAX_N-1], MOD - 2, MOD)
    for i in range(MAX_N-2, -1, -1):
        finv[i] = (finv[i+1] * (i + 1)) % MOD

    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        return fact[n] * finv[r] % MOD * finv[n-r] % MOD

    answers = {}

    # For each n, compute f_r(n) for all r
    for n in range(1, MAX_N):
        # Get prime factorization and counts
        temp = n
        counts = []
        while temp > 1:
            p = spf[temp]
            cnt = 0
            while temp % p == 0:
                cnt += 1
                temp //= p
            counts.append(cnt)

        if not counts:
            answers[(0, n)] = 1
            continue

        # Precompute for all r
        for r in range(T_MAX):
            result = 1
            for cnt in counts:
                # binomial(cnt + r - 1, r) = (cnt+r-1)! / (cnt! * (r-1)!)
                # Using nCr(cnt + r - 1, r)
                result = (result * nCr(cnt + r - 1, r)) % MOD
            answers[(r, n)] = result

    return answers, spf, fact, finv

