    # Filter redundant xs - only keep values that aren't multiples of smaller values
    xs.sort()
    unique_x = []
    for x in xs:
        is_multiple = False
        for ux in unique_x:
            if x % ux == 0:
                is_multiple = True
                break
        if not is_multiple:
            unique_x.append(x)
    xs = unique_x

    # BFS from a to find minimum operations to reach b
    dist = {}
    queue = deque([a])
    dist[a] = 0

    while queue:
        curr = queue.popleft()

        if curr == b:
            return str(dist[curr]) + "\n"

        # Limit depth to max possible answer
        if dist[curr] >= a - b:
            continue

        # Operation 1: subtract 1
        next_val = curr - 1
        if next_val >= b and next_val not in dist:
            dist[next_val] = dist[curr] + 1
            queue.append(next_val)

        # Operation 2: subtract (curr mod xi)
        for x in xs:
            mod_val = curr % x
            if mod_val > 0:
                next_val = curr - mod_val
                if next_val >= b and next_val not in dist:
                    dist[next_val] = dist[curr] + 1
                    queue.append(next_val)

    return str(a - b) + "\n"

