from collections import deque


def solution(tree_input):
    """
    Find minimum operations to transform tree into star.

    The solution is radius - 1, where radius is the minimum eccentricity of the tree.
    radius = diameter // 2 (using double BFS technique)
    So answer = diameter // 2 - 1
    """
    lines = tree_input.strip().split('\n')
    n = int(lines[0])

    if n <= 2:
        return "0\n"

    adj = [[] for _ in range(n + 1)]
    for line in lines[1:]:
        u, v = map(int, line.split())
        adj[u].append(v)
        adj[v].append(u)

    def bfs(start):
        """BFS from start, return (farthest_vertex, max_distance)"""
        dist = [-1] * (n + 1)
        dist[start] = 0
        queue = deque([start])
        farthest = start
        max_dist = 0

        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append(v)
                    if dist[v] > max_dist:
                        max_dist = dist[v]
                        farthest = v
        return farthest, max_dist

    # Double BFS to find diameter
    _, first_end = bfs(1)
    _, diameter = bfs(first_end)

    # Radius = diameter // 2
    # Answer = radius - 1
    return f"{diameter // 2 - 1}\n"


