                depth[v] = depth[u] + 1
                parent[v] = u
                queue.append(v)

    def lca_find(u, v):
        if depth[u] < depth[v]:
            u, v = v, u

        while depth[u] > depth[v]:
            u = parent[u]

        while u != v:
            u = parent[u]
            v = parent[v]

        return u

