def get_prime_factors(n):
    """Get unique prime factors of n."""
    factors = set()
    d = 2
    while d * d <= n:
        if n % d == 0:
            factors.add(d)
            while n % d == 0:
                n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        factors.add(n)
    return factors

def mod_pow(a, b, m):
    """Compute (a^b) % m efficiently."""
    if m == 1:
        return 0
    result = 1
    a = a % m
    while b > 0:
        if b & 1:
            result = (result * a) % m
        a = (a * a) % m
        b >>= 1
    return result

def find_multiplicative_order(a, p):
    """Find multiplicative order of a modulo p (assume p is prime)."""
    if p == 1:
        return 1
    if a % p == 0:
        return -1  # Order doesn't exist

    phi = p - 1
    order = phi

    # Factorize phi and try to reduce order
    temp = phi
    d = 2
    while d * d <= temp:
        if temp % d == 0:
            while temp % d == 0:
                temp //= d
            # Try reducing order by prime factor d
            while order % d == 0:
                if mod_pow(a, order // d, p) == 1:
                    order //= d
                else:
                    break
        d += 1 if d == 2 else 2
    if temp > 1:
        while order % temp == 0:
            if mod_pow(a, order // temp, p) == 1:
                order //= temp
            else:
                break

    return order

def solution(input_str):
    n, x = map(int, input_str.strip().split())

    # Special case: n = 1, any b > 1 works
    if n == 1:
        if x - 1 > 1:
            return str(x - 1) + '\n'
        else:
            return "-1\n"

    # Try to find the largest base from x-1 down to 2
    for b in range(x - 1, 1, -1):
        # Calculate b^n - 1
        bn_minus_1 = b ** n - 1

        if bn_minus_1 == 0:
            continue

        # Get prime factors of b^n - 1
        prime_factors = get_prime_factors(bn_minus_1)

        # Check each prime factor
        for p in prime_factors:
            if p == 1:
                continue

            # Check if multiplicative order of b mod p equals n
            order = find_multiplicative_order(b, p)

            if order == n:
                return str(b) + '\n'

    return "-1\n"

