from collections import deque

def solution(input_str):
    n = int(input_str.strip())
    if n == 0:
        return "0\n"

    queue = deque([(n, 0)])
    visited = {n}

    while queue:
        current, steps = queue.popleft()

        if current == 0:
            return str(steps) + "\n"

        digits = set(int(d) for d in str(current))

        for d in digits:
            if d == 0:
                continue  # Can't reduce by subtracting 0
            next_val = current - d
            if next_val >= 0 and next_val not in visited:
                visited.add(next_val)
                queue.append((next_val, steps + 1))

    return str(0) + "\n"
